.extern Add_7
.global Asm_Add_7
  .type Asm_Add_7, %function
Asm_Add_7:
  push {r4, lr} // 컨텍스트 저장

  // r1, r2, r3에 a 저장
  mov r1, r0 // a
  mov r2, r0
  mov r3, r0

  // a를 3번 스택에 push
  sub sp, sp, #12 // 스택 포인터 12바이트 감소
  str r0, [sp, #8]
  str r0, [sp, #4]
  str r0, [sp]

  // Add_7 함수 호출
  bl Add_7

  // Add_7의 반환값과 b 더하기
  add r0, r0, r1

  // 스택 포인터 복원
  add sp, sp, #12

  pop {r4, pc} // 컨텍스트 복원 및 함수 종료

